begin;

-- Cờ tỷ phú · TUYỂN CHỌN CẦU THỦ bằng Huy Hiệu Tuyển Chọn (quà mốc đặc biệt 12.600 điểm). Chạy SAU 202611220003_fco_ctp_cards.sql. Chạy lại được.
-- Theo trang sự kiện gốc Tỷ Phú 2.0 (fconline.garena.vn/ty-phu-t11-2026):
--   · Mỗi mùa một cấp thẻ cố định: +1 PRM / ICON TM, +8 GRU / BLD / CU, +9 MDL / UT / 24EP, +10 HG / RTN / CC / FCA / DC / JNM,
--     +11 FA / LOL / LN / SPL / 23HW, +12 EBS / BOE21 / CAP (ICONS +6 và RMA +11 game chưa có). Danh sách cầu thủ hợp lệ = bảng
--     fco_ctp_draft_pool (sinh từ dữ liệu game, khớp CTP_DRAFT ở src/ctp.ts).
--   · Lượt mở thứ 1 / 2 / 3 / từ 4: chọn đủ 10 / 9 / 7 / 5 cầu thủ khác nhau, tổng giá trị (giá thị trường hiện tại) ≤ 6.000.000.000 BP.
--   · Mỗi lần dùng 1 huy hiệu → nhận ngẫu nhiên 1 cầu thủ trong nhóm, tỷ lệ NGHỊCH VỚI GIÁ (người dùng chọn 2026-11-22).

do $$
declare n integer;
begin
  -- Dữ liệu cầu thủ trên máy chủ phải có đủ người trong danh sách (đồng bộ từ game).
  create temp table if not exists _ctp_pool_check (player_id integer, level smallint) on commit drop;
  select count(*) into n from _ctp_pool_check c where not exists (select 1 from public.fco_cat_players p where p.id = c.player_id);
  if n > 0 then raise exception 'Máy chủ thiếu % cầu thủ của Tuyển chọn: đưa bản game mới lên → Quản trị FC → Đồng bộ dữ liệu, rồi chạy lại migration này.', n; end if;
end $$;

create table if not exists public.fco_ctp_draft_pool (
  player_id integer primary key,
  level smallint not null check (level between 1 and 13)
);
alter table public.fco_ctp_draft_pool enable row level security;
revoke all on public.fco_ctp_draft_pool from anon, authenticated;
delete from public.fco_ctp_draft_pool;

alter table public.fco_wallets add column if not exists ctp_draft_count integer not null default 0 check (ctp_draft_count >= 0);

-- Như 202611220003, 'ctp' thêm số lượt đã mở Tuyển chọn (quyết định số cầu thủ phải chọn).
create or replace function public.fco_wallet_json(p_uid uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'fc', w.fc,
    'stp', w.stp,
    'dailyClaimed', w.daily is not distinct from public.fco_today(),
    'event', jsonb_build_object(
      'points', w.event_points, 'free', w.event_free,
      'paid', case when w.event_day = public.fco_today() then w.event_paid else 0 end,
      'missions', case when w.event_day = public.fco_today() then to_jsonb(w.event_missions) else '[]'::jsonb end),
    'checkin', case when w.checkin_date = public.fco_today()
      then jsonb_build_object('claimedToday', true, 'day', w.checkin_day, 'done', w.checkin_day)
      else jsonb_build_object('claimedToday', false, 'day', public.fco_checkin_next(w.checkin_day, w.checkin_date, public.fco_today()),
                              'done', public.fco_checkin_next(w.checkin_day, w.checkin_date, public.fco_today()) - 1) end,
    'bilac', jsonb_build_object('points', w.bilac_points, 'claimed', to_jsonb(w.bilac_claimed), 'freeToday', w.bilac_free_day is distinct from public.fco_today()),
    'vqtg', jsonb_build_object('pos', w.vqtg_pos, 'picks', w.vqtg_picks, 'tickets', w.vqtg_tickets, 'freeToday', w.vqtg_free_day is distinct from public.fco_today(),
      'claimed', to_jsonb(w.vqtg_claimed), 'paid', public.fco_vqtg_paid(w.user_id)),
    'ctp', jsonb_build_object('pos', w.ctp_pos, 'points', w.ctp_points, 'free', w.ctp_free, 'lucky', w.ctp_lucky, 'firstDone', w.ctp_first_done,
      'mission', public.fco_ctp_mission(w), 'claimed', to_jsonb(w.ctp_claimed), 'paid', public.fco_ctp_paid(w.user_id),
      'cards', jsonb_build_object('chance', w.ctp_card_chance, 'luck', w.ctp_card_luck), 'badges', w.ctp_badges,
      'pending', exists (select 1 from public.fco_ctp_pending p where p.user_id = w.user_id), 'draftOpened', w.ctp_draft_count),
    'membership', jsonb_build_object(
      'svip', (extract(epoch from w.svip_until) * 1000)::bigint,
      'premium', (extract(epoch from w.premium_until) * 1000)::bigint),
    'tier', public.fco_account_tier(w.user_id),
    'tierUntil', case when public.fco_account_tier(w.user_id) <> 'classic' then (extract(epoch from w.account_tier_until) * 1000)::bigint end,
    'effect', public.fco_name_effect(w.user_id),
    'club', w.club_logo,
    'admin', exists (select 1 from public.fco_admins a where a.user_id = w.user_id))
  from public.fco_wallets w where w.user_id = p_uid
$$;

-- Như 202611220003, reset thêm số lượt Tuyển chọn.
create or replace function public.fco_admin_account_reset(p_user uuid, p_reset_fc boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare admin_id uuid := public.fco_require_admin(); w public.fco_wallets; old_data jsonb; remaining bigint;
begin
  if not exists (select 1 from auth.users where id = p_user) then raise exception 'FCO_USER_NOT_FOUND' using errcode = 'P0001'; end if;
  if p_reset_fc is null then raise exception 'Invalid reset option' using errcode = '22023'; end if;
  w := public.fco_wallet_lock(p_user);
  remaining := case when p_reset_fc then 0 else w.fc end;
  update public.fco_wallets set fc = remaining, event_points = 0, event_free = 0, event_paid = 0, event_missions = '{}',
    bilac_points = 0, bilac_claimed = '{}', checkin_day = 0,
    vqtg_pos = 0, vqtg_picks = 0, vqtg_tickets = 0, vqtg_tickets_at = null, vqtg_claimed = '{}',
    ctp_pos = 28, ctp_points = 0, ctp_free = 0, ctp_lucky = 1, ctp_claimed = '{}', ctp_card_chance = 0, ctp_card_luck = 0, ctp_badges = 0, ctp_draft_count = 0, updated_at = now()
  where user_id = p_user;
  select data into old_data from public.fco_game_saves where user_id = p_user for update;
  -- Chưa có bản lưu thì không có gì để xoá; lần đầu vào game sẽ tự tạo bản trống.
  if found then
    update public.fco_game_saves set revision = revision + 1, updated_at = now(), data =
      jsonb_build_object('version', 1, 'balance', 0, 'cards', '[]'::jsonb, 'history', '[]'::jsonb, 'unopened', '{}'::jsonb, 'daily', '', 'opened', 0, 'upgrades', 0,
        'sound', coalesce(old_data->'sound', 'false'::jsonb), 'reduced', coalesce(old_data->'reduced', 'false'::jsonb))
      || jsonb_strip_nulls(jsonb_build_object('reset', old_data->'reset', 'bpReset', old_data->'bpReset', 'quick', old_data->'quick', 'light', old_data->'light', 'codes', old_data->'codes'))
    where user_id = p_user;
  end if;
  delete from public.fco_ranks where user_id = p_user;
  delete from public.fco_ctp_pending where user_id = p_user;
  values (p_user, remaining - w.fc, remaining, 'reset', jsonb_build_object('resetFc', p_reset_fc), admin_id);
  return jsonb_build_object('reset', true, 'fc', remaining);
end;
$$;

-- Tuyển chọn: p_players = đúng N cầu thủ khác nhau trong danh sách hợp lệ (N theo số lượt đã mở), tổng giá ≤ 6 tỷ BP; trừ 1 huy hiệu,
-- nhận ngẫu nhiên 1 người (tỷ lệ nghịch giá) vào kho máy chủ.
create or replace function public.fco_ctp_draft(p_players integer[]) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := public.fco_require_user(); w public.fco_wallets; need integer; n integer := coalesce(array_length(p_players, 1), 0);
  total numeric := 0; inv_sum double precision := 0; r double precision; acc double precision := 0; picked integer; lvl integer; rec record;
  d jsonb; card jsonb; chances jsonb := '[]';
begin
  if not public.fco_ctp_open() then raise exception 'FCO_EVENT_CLOSED' using errcode = 'P0001'; end if;
  w := public.fco_wallet_lock(uid);
  if w.ctp_badges < 1 then raise exception 'FCO_CTP_NO_BADGE' using errcode = 'P0001'; end if;
  need := case when w.ctp_draft_count = 0 then 10 when w.ctp_draft_count = 1 then 9 when w.ctp_draft_count = 2 then 7 else 5 end;
  if n <> need or (select count(distinct x) from unnest(p_players) x) <> need then raise exception 'FCO_CTP_DRAFT_SIZE' using errcode = '22023'; end if;
  create temp table if not exists _ctp_draft (player_id integer, level integer, price bigint) on commit drop;
  delete from _ctp_draft;
  if exists (select 1 from _ctp_draft where level is null) then raise exception 'FCO_CTP_DRAFT_PLAYER' using errcode = '22023'; end if;
  if exists (select 1 from _ctp_draft where coalesce(price, 0) <= 0) then raise exception 'FCO_CTP_DRAFT_PRICE' using errcode = 'P0001'; end if;
  select sum(price), sum(1.0 / price) into total, inv_sum from _ctp_draft;
  if total > 6000000000 then raise exception 'FCO_CTP_DRAFT_CAP' using errcode = 'P0001'; end if;
  r := random() * inv_sum;
  for rec in select * from _ctp_draft order by player_id loop
    acc := acc + 1.0 / rec.price;
    chances := chances || jsonb_build_object('playerId', rec.player_id, 'level', rec.level, 'price', rec.price, 'chance', round((1.0 / rec.price / inv_sum)::numeric, 6));
    if picked is null and r < acc then picked := rec.player_id; lvl := rec.level; end if;
  end loop;
  if picked is null then select player_id, level into picked, lvl from _ctp_draft order by price limit 1; end if;
  update public.fco_wallets set ctp_badges = ctp_badges - 1, ctp_draft_count = ctp_draft_count + 1 where user_id = uid;
  d := public.fco_inv_lock(uid);
  card := public.fco_inv_new_card(picked, lvl);
  d := d || jsonb_build_object('cards', jsonb_build_array(card) || coalesce(d->'cards', '[]'));
  d := public.fco_inv_history(d, 'event', 'Cờ tỷ phú · Tuyển chọn cầu thủ (lượt ' || (w.ctp_draft_count + 1) || ')',
    public.fco_inv_name(picked) || ' +' || lvl || ' · OVR ' || public.fco_inv_ovr(picked, lvl) || ' · chọn từ ' || need || ' cầu thủ, tổng ' || public.fco_inv_money(total::bigint) || ' BP');
  return jsonb_build_object('card', card, 'playerId', picked, 'level', lvl, 'chances', chances, 'total', total::bigint,
    'wallet', public.fco_wallet_json(uid), 'save', public.fco_inv_store(uid, d));
end;
$$;

revoke all on function public.fco_ctp_draft(integer[]) from public, anon;
grant execute on function public.fco_ctp_draft(integer[]) to authenticated;

commit;
